if (legalMoves(s).length !== 0) throw new Error('terminal has legal moves');

// Fill win: known drawn board -> O
s = play([0, 1, 2, 4, 5, 3, 6, 8, 7]);
st = status(s);
console.log('fill:', JSON.stringify(st));
if (st.reason !== 'fill' || st.winner !== 'O' || st.line !== null) throw new Error('bad fill');

// Fresh game
st = status(createGame());
console.log('fresh:', JSON.stringify(st));
if (st.reason !== null || st.line !== null) throw new Error('fresh game not clear');

console.log('OK');
EOF
